B=[
('الرِّحْلَةُ الثَّالِثَةُ: جَزِيرَةُ الْقُرُودِ','Üçüncü yolculuk: Maymunlar adası',[
('فِي الْيَوْمِ الثَّالِثِ جَلَسَ الْحَمَّالُ يَسْمَعُ، فَقَالَ السِّنْدِبَادُ:','Üçüncü gün hamal dinlemek için oturdu; Sindbad dedi ki:'),
('«بَعْدَ زَمَنٍ قَصِيرٍ نَسِيتُ الْخَوْفَ، وَاشْتَقْتُ إِلَى السَّفَرِ مَرَّةً أُخْرَى.»','“Kısa bir süre sonra korkuyu unuttum ve yine yolculuğu özledim.”'),
('«فَرَكِبْتُ سَفِينَةً مِنَ الْبَصْرَةِ، وَسَافَرْنَا أَيَّامًا كَثِيرَةً.»','“Basra’dan bir gemiye bindim ve uzun günler yol aldık.”'),
('«وَفِي يَوْمٍ هَبَّتْ رِيحٌ شَدِيدَةٌ، فَضَاعَ الطَّرِيقُ مِنَّا.»','“Bir gün şiddetli bir rüzgâr esti ve yolumuzu kaybettik.”'),
('«نَظَرَ الْقُبْطَانُ إِلَى جَزِيرَةٍ قَرِيبَةٍ، وَبَكَى وَقَالَ: هَذِهِ جَزِيرَةُ الْقُرُودِ!»','“Kaptan yakındaki bir adaya baktı, ağladı ve dedi ki: Bu maymunlar adası!”'),
('«وَقَبْلَ أَنْ نَفْهَمَ، جَاءَتْ قُرُودٌ كَثِيرَةٌ جِدًّا، مِثْلَ الْجَرَادِ.»','“Biz anlamadan çekirgeler gibi çok sayıda maymun geldi.”'),
('«صَعِدَتِ الْقُرُودُ إِلَى السَّفِينَةِ، وَقَطَعَتِ الْحِبَالَ، وَأَخَذَتِ السَّفِينَةَ.»','“Maymunlar gemiye çıktı, halatları kesti ve gemiyi aldı.”'),
('«وَتَرَكَتْنَا عَلَى الْجَزِيرَةِ وَحْدَنَا.»','“Ve bizi adada yalnız bıraktı.”')]),
('الْقَصْرُ الْأَسْوَدُ','Kara saray',[
('«مَشَيْنَا فِي الْجَزِيرَةِ نَأْكُلُ مِنَ الثِّمَارِ وَنَشْرَبُ مِنَ الْأَنْهَارِ.»','“Adada meyvelerden yiyip nehirlerden içerek yürüdük.”'),
('«ثُمَّ رَأَيْنَا قَصْرًا عَالِيًا، بَابُهُ مَفْتُوحٌ، وَجُدْرَانُهُ سَوْدَاءُ.»','“Sonra kapısı açık, duvarları siyah yüksek bir saray gördük.”'),
('«دَخَلْنَا فَوَجَدْنَا عِظَامًا كَثِيرَةً، وَقُدُورًا كَبِيرَةً عَلَى النَّارِ.»','“İçeri girdik; çok sayıda kemik ve ateşin üstünde büyük kazanlar bulduk.”'),
('«كُنَّا تَعْبَانِينَ، فَنِمْنَا فِي الْقَصْرِ.»','“Yorgunduk; sarayda uyuduk.”'),
('«وَعِنْدَ الْمَسَاءِ اهْتَزَّتِ الْأَرْضُ، وَسَمِعْنَا صَوْتًا مِثْلَ الرَّعْدِ.»','“Akşam yer sarsıldı ve gök gürültüsü gibi bir ses duyduk.”'),
('«فَدَخَلَ عِمْلَاقٌ أَسْوَدُ، طَوِيلٌ مِثْلَ النَّخْلَةِ، لَهُ عَيْنٌ وَاحِدَةٌ تَلْمَعُ مِثْلَ النَّارِ.»','“Hurma ağacı kadar uzun, ateş gibi parlayan tek gözü olan kara bir dev içeri girdi.”'),
('«فَخِفْنَا خَوْفًا شَدِيدًا، وَلَمْ نَسْتَطِعِ الْكَلَامَ.»','“Çok korktuk ve konuşamadık.”')]),
('الْعِمْلَاقُ','Dev',[
('«جَلَسَ الْعِمْلَاقُ وَنَظَرَ إِلَيْنَا وَاحِدًا وَاحِدًا.»','“Dev oturdu ve bize tek tek baktı.”'),
('«ثُمَّ أَخَذَنِي بِيَدِهِ وَرَفَعَنِي، لَكِنِّي كُنْتُ نَحِيفًا، فَتَرَكَنِي.»','“Sonra beni eliyle tutup kaldırdı; ama zayıftım, beni bıraktı.”'),
('«وَأَخَذَ الْقُبْطَانَ، لِأَنَّهُ كَانَ سَمِينًا.»','“Kaptanı aldı, çünkü şişmandı.”'),
('«فَأَكَلَهُ، ثُمَّ نَامَ وَهُوَ يَشْخِرُ بِصَوْتٍ عَالٍ.»','“Onu yedi, sonra yüksek sesle horlayarak uyudu.”'),
('«بَكَيْنَا طُولَ اللَّيْلِ، وَقُلْنَا: يَا لَيْتَنَا غَرِقْنَا فِي الْبَحْرِ!»','“Bütün gece ağladık ve dedik ki: Keşke denizde boğulsaydık!”'),
('«وَفِي الصَّبَاحِ خَرَجَ الْعِمْلَاقُ، وَتَرَكَنَا فِي الْقَصْرِ.»','“Sabah dev çıktı ve bizi sarayda bıraktı.”')]),
('الْخُطَّةُ','Plan',[
('«قُلْتُ لِأَصْحَابِي: لَا نَجْلِسُ وَنَبْكِي، تَعَالَوْا نُفَكِّرْ.»','“Arkadaşlarıma dedim ki: Oturup ağlamayalım; gelin düşünelim.”'),
('«نَصْنَعُ قَارِبًا مِنَ الْخَشَبِ، وَنَضَعُهُ عِنْدَ الْبَحْرِ.»','“Tahtadan bir sal yapalım ve deniz kenarına koyalım.”'),
('«ثُمَّ نُحَمِّي حَدِيدَتَيْنِ فِي النَّارِ، وَنَضَعُهُمَا فِي عَيْنِهِ وَهُوَ نَائِمٌ.»','“Sonra iki demiri ateşte kızdıralım ve o uyurken gözüne sokalım.”'),
('«فَإِنْ مَاتَ نَجَوْنَا، وَإِنْ لَمْ يَمُتْ هَرَبْنَا فِي الْقَارِبِ.»','“Ölürse kurtuluruz; ölmezse salla kaçarız.”'),
('«فَعَمِلْنَا طُولَ النَّهَارِ، وَصَنَعْنَا الْقَارِبَ.»','“Bütün gün çalıştık ve salı yaptık.”'),
('«وَفِي اللَّيْلِ رَجَعَ الْعِمْلَاقُ، فَأَكَلَ رَجُلًا آخَرَ وَنَامَ.»','“Gece dev döndü, bir adamı daha yedi ve uyudu.”')]),
('الْهَرَبُ','Kaçış',[
('«قُمْنَا بِهُدُوءٍ، وَحَمَّيْنَا الْحَدِيدَ حَتَّى صَارَ أَحْمَرَ.»','“Sessizce kalktık ve demiri kızarana kadar ısıttık.”'),
('«ثُمَّ وَضَعْنَاهُ فِي عَيْنِهِ بِكُلِّ قُوَّتِنَا.»','“Sonra bütün gücümüzle onu gözüne soktuk.”'),
('«صَاحَ الْعِمْلَاقُ صَيْحَةً عَظِيمَةً، وَقَامَ يَبْحَثُ عَنَّا، لَكِنَّهُ لَا يَرَى.»','“Dev korkunç bir çığlık attı ve bizi aramak için kalktı, ama göremiyordu.”'),
('«فَرَكَضْنَا إِلَى الْبَحْرِ، وَرَكِبْنَا الْقَارِبَ.»','“Denize koştuk ve sala bindik.”'),
('«فَجَاءَ الْعِمْلَاقُ وَمَعَهُ عِمْلَاقَةٌ أَكْبَرُ مِنْهُ، وَرَمَيَا عَلَيْنَا الْحِجَارَةَ.»','“Dev, yanında kendisinden daha büyük bir dişi devle geldi ve bize taş attılar.”'),
('«فَمَاتَ أَكْثَرُ أَصْحَابِي، وَنَجَوْتُ أَنَا وَرَجُلَانِ فَقَطْ.»','“Arkadaşlarımın çoğu öldü; yalnızca ben ve iki adam kurtulduk.”')]),
('الْحَيَّةُ الْعَظِيمَةُ','Dev yılan',[
('«حَمَلَتْنَا الْأَمْوَاجُ إِلَى جَزِيرَةٍ أُخْرَى، فَنِمْنَا تَحْتَ شَجَرَةٍ.»','“Dalgalar bizi başka bir adaya taşıdı; bir ağacın altında uyuduk.”'),
('«وَفِي اللَّيْلِ جَاءَتْ حَيَّةٌ عَظِيمَةٌ، فَأَكَلَتْ أَحَدَ صَاحِبَيَّ.»','“Gece dev bir yılan geldi ve iki arkadaşımdan birini yuttu.”'),
('«فَصَعِدْنَا أَنَا وَالْآخَرُ إِلَى أَعْلَى الشَّجَرَةِ.»','“Ben ve diğeri ağacın tepesine tırmandık.”'),
('«لَكِنَّ الْحَيَّةَ صَعِدَتْ فِي اللَّيْلَةِ الثَّانِيَةِ، وَأَكَلَتْ صَاحِبِي الْآخَرَ.»','“Ama ikinci gece yılan tırmandı ve öbür arkadaşımı da yuttu.”'),
('«فَبَقِيتُ وَحْدِي، وَقُلْتُ: لَا بُدَّ مِنْ حِيلَةٍ.»','“Yalnız kaldım ve dedim ki: Bir çare bulmak şart.”'),
('«فَأَخَذْتُ أَلْوَاحًا مِنَ الْخَشَبِ، وَرَبَطْتُهَا حَوْلَ جِسْمِي مِنْ كُلِّ جِهَةٍ.»','“Tahta levhalar aldım ve onları vücudumun her yanına bağladım.”'),
('«فَجَاءَتِ الْحَيَّةُ، وَدَارَتْ حَوْلِي، لَكِنَّهَا لَمْ تَسْتَطِعْ أَنْ تَبْلَعَنِي.»','“Yılan geldi, etrafımda döndü, ama beni yutamadı.”'),
('«وَفِي الصَّبَاحِ ذَهَبَتْ غَاضِبَةً.»','“Sabah öfkeyle gitti.”')]),
('الْعَوْدَةُ الثَّالِثَةُ','Üçüncü dönüş',[
('«رَكَضْتُ إِلَى الشَّاطِئِ، فَرَأَيْتُ سَفِينَةً بَعِيدَةً.»','“Kıyıya koştum ve uzakta bir gemi gördüm.”'),
('«لَوَّحْتُ بِثَوْبِي وَصِحْتُ، فَرَآنِي الْبَحَّارَةُ، وَأَخَذُونِي.»','“Elbisemi salladım ve bağırdım; denizciler beni gördü ve aldılar.”'),
('«وَكَانَتِ الْمُفَاجَأَةُ: هَذِهِ هِيَ السَّفِينَةُ الَّتِي تَرَكَتْنِي فِي الرِّحْلَةِ الثَّانِيَةِ!»','“Ve sürpriz şuydu: Bu, ikinci yolculukta beni bırakan gemiydi!”'),
('«وَكَانَتْ بِضَاعَتِي مَا زَالَتْ فِيهَا، فَأَعْطَانِي الْقُبْطَانُ إِيَّاهَا.»','“Mallarım hâlâ içindeydi; kaptan onları bana verdi.”'),
('«فَبِعْتُهَا فِي الْجُزُرِ، وَرَبِحْتُ رِبْحًا كَبِيرًا، وَرَجَعْتُ إِلَى بَغْدَادَ.»','“Onları adalarda sattım, büyük kâr ettim ve Bağdat’a döndüm.”'),
('ثُمَّ قَالَ السِّنْدِبَادُ لِلْحَمَّالِ: «أَرَأَيْتَ؟ كُلُّ دِينَارٍ عِنْدِي لَهُ قِصَّةٌ. تَعَالَ غَدًا لِلرِّحْلَةِ الرَّابِعَةِ.»','Sonra Sindbad hamala dedi ki: “Gördün mü? Bendeki her dinarın bir hikâyesi var. Yarın dördüncü yolculuk için gel.”')]),
]
